import React, { useState, useEffect } from 'react';
import { ShoppingBag, Heart, LogOut, ArrowRight, ArrowLeft, ChevronLeft, User as UserIcon, Plus, Trash2, Edit3, Check, Package } from 'lucide-react';
import { Product, UserOrder } from '../types';
import { ALL_PRODUCTS } from '../data/mockData';
import { formatTomanPrice } from '../utils/persianNumbers';

export interface AddressItem {
  id: string;
  title: string;
  province: string;
  city: string;
  fullAddress: string;
  postalCode: string;
  plaque: string;
  unit: string;
  recipientName: string;
  recipientPhone: string;
  isDefault: boolean;
}

interface ProfilePageProps {
  userPhone: string;
  userName?: string;
  onUpdateUserName: (name: string) => void;
  onLogout: () => void;
  onNavigateHome: () => void;
  onNavigateToProducts: (filter?: any) => void;
  garderobIds: string[];
  onOpenProductDetail: (product: Product) => void;
  onToggleGarderob?: (product: Product) => void;
  initialSubView?: 'menu' | 'orders' | 'wishlist' | 'addresses' | 'personal-info';
}

export const ProfilePage: React.FC<ProfilePageProps> = ({
  userPhone,
  userName = '',
  onUpdateUserName,
  onLogout,
  onNavigateHome,
  onNavigateToProducts,
  garderobIds,
  onOpenProductDetail,
  onToggleGarderob,
  initialSubView = 'menu',
}) => {
  // Navigation: 'menu' (main list) or sub-views corresponding to the menu items
  const [currentSubView, setCurrentSubView] = useState<'menu' | 'orders' | 'wishlist' | 'addresses' | 'personal-info'>(initialSubView);

  // Sync initialSubView when changed from parent
  useEffect(() => {
    if (initialSubView) {
      setCurrentSubView(initialSubView);
    }
  }, [initialSubView]);

  // Orders State (Read from lengeh_user_orders)
  const [orders, setOrders] = useState<UserOrder[]>(() => {
    try {
      const saved = localStorage.getItem('lengeh_user_orders');
      if (saved) {
        const parsed = JSON.parse(saved);
        if (Array.isArray(parsed)) return parsed;
      }
    } catch {}
    return [];
  });

  // Re-read orders when subview changes to 'orders'
  useEffect(() => {
    if (currentSubView === 'orders') {
      try {
        const saved = localStorage.getItem('lengeh_user_orders');
        if (saved) {
          const parsed = JSON.parse(saved);
          if (Array.isArray(parsed)) setOrders(parsed);
        }
      } catch {}
    }
  }, [currentSubView]);

  // Confirmation modal for logout
  const [isLogoutModalOpen, setIsLogoutModalOpen] = useState(false);

  // Notice banner inside sub-views
  const [noticeMsg, setNoticeMsg] = useState<string | null>(null);

  // Convert English digits to Persian digits
  const toPersianDigits = (str: string | number) => {
    const persianMap = ['۰', '۱', '۲', '۳', '۴', '۵', '۶', '۷', '۸', '۹'];
    return String(str || '').replace(/[0-9]/g, (w) => persianMap[+w]);
  };

  const showNotice = (msg: string) => {
    setNoticeMsg(msg);
    setTimeout(() => {
      setNoticeMsg((curr) => (curr === msg ? null : curr));
    }, 2800);
  };

  // Personal Info State
  const [firstName, setFirstName] = useState(() => {
    try {
      const saved = localStorage.getItem('lengeh_user_profile');
      if (saved) {
        const parsed = JSON.parse(saved);
        if (parsed.firstName) return parsed.firstName;
      }
    } catch {}
    if (userName) {
      const parts = userName.split(' ');
      return parts[0] || '';
    }
    return '';
  });

  const [lastName, setLastName] = useState(() => {
    try {
      const saved = localStorage.getItem('lengeh_user_profile');
      if (saved) {
        const parsed = JSON.parse(saved);
        if (parsed.lastName) return parsed.lastName;
      }
    } catch {}
    if (userName) {
      const parts = userName.split(' ');
      return parts.slice(1).join(' ') || '';
    }
    return '';
  });

  const [nationalCode, setNationalCode] = useState(() => {
    try {
      const saved = localStorage.getItem('lengeh_user_profile');
      if (saved) return JSON.parse(saved).nationalCode || '';
    } catch {}
    return '';
  });

  const [email, setEmail] = useState(() => {
    try {
      const saved = localStorage.getItem('lengeh_user_profile');
      if (saved) return JSON.parse(saved).email || '';
    } catch {}
    return '';
  });

  const handleSavePersonalInfo = (e: React.FormEvent) => {
    e.preventDefault();
    const fullName = `${firstName.trim()} ${lastName.trim()}`.trim();
    onUpdateUserName(fullName);
    try {
      const profileData = {
        firstName: firstName.trim(),
        lastName: lastName.trim(),
        nationalCode: nationalCode.trim(),
        email: email.trim(),
        phone: userPhone,
      };
      localStorage.setItem('lengeh_user_profile', JSON.stringify(profileData));
    } catch {}
    showNotice('اطلاعات حساب کاربری با موفقیت بروزرسانی شد');
    setCurrentSubView('menu');
  };

  // Addresses State
  const [addresses, setAddresses] = useState<AddressItem[]>(() => {
    try {
      const saved = localStorage.getItem('lengeh_user_addresses');
      if (saved) return JSON.parse(saved);
    } catch {}
    return [];
  });

  const [isAddressFormOpen, setIsAddressFormOpen] = useState(false);
  const [editingAddressId, setEditingAddressId] = useState<string | null>(null);
  const [addressForm, setAddressForm] = useState({
    title: 'منزل',
    province: 'تهران',
    city: 'تهران',
    fullAddress: '',
    postalCode: '',
    plaque: '',
    unit: '',
    recipientName: userName || '',
    recipientPhone: userPhone || '',
    isDefault: true,
  });

  const handleOpenAddAddress = () => {
    setEditingAddressId(null);
    setAddressForm({
      title: 'منزل',
      province: 'تهران',
      city: 'تهران',
      fullAddress: '',
      postalCode: '',
      plaque: '',
      unit: '',
      recipientName: `${firstName} ${lastName}`.trim() || userName || '',
      recipientPhone: userPhone || '',
      isDefault: addresses.length === 0,
    });
    setIsAddressFormOpen(true);
  };

  const handleOpenEditAddress = (addr: AddressItem) => {
    setEditingAddressId(addr.id);
    setAddressForm({
      title: addr.title,
      province: addr.province,
      city: addr.city,
      fullAddress: addr.fullAddress,
      postalCode: addr.postalCode,
      plaque: addr.plaque,
      unit: addr.unit,
      recipientName: addr.recipientName,
      recipientPhone: addr.recipientPhone,
      isDefault: addr.isDefault,
    });
    setIsAddressFormOpen(true);
  };

  const handleDeleteAddress = (id: string) => {
    const updated = addresses.filter((a) => a.id !== id);
    if (updated.length > 0 && !updated.some((a) => a.isDefault)) {
      updated[0].isDefault = true;
    }
    setAddresses(updated);
    try {
      localStorage.setItem('lengeh_user_addresses', JSON.stringify(updated));
    } catch {}
    showNotice('آدرس حذف شد');
  };

  const handleSaveAddress = (e: React.FormEvent) => {
    e.preventDefault();
    if (!addressForm.fullAddress.trim()) return;

    let updated: AddressItem[];
    if (editingAddressId) {
      updated = addresses.map((a) => {
        if (a.id === editingAddressId) {
          return {
            ...a,
            ...addressForm,
          };
        }
        return addressForm.isDefault ? { ...a, isDefault: false } : a;
      });
    } else {
      const newAddr: AddressItem = {
        id: `addr_${Date.now()}`,
        ...addressForm,
      };
      if (addressForm.isDefault) {
        updated = [...addresses.map((a) => ({ ...a, isDefault: false })), newAddr];
      } else {
        updated = [...addresses, newAddr];
      }
    }

    setAddresses(updated);
    try {
      localStorage.setItem('lengeh_user_addresses', JSON.stringify(updated));
    } catch {}
    setIsAddressFormOpen(false);
    setEditingAddressId(null);
    showNotice('آدرس با موفقیت ذخیره شد');
  };

  // Saved Wishlist products
  const savedWishlistProducts = ALL_PRODUCTS.filter((p) => garderobIds.includes(p.id));

  // Custom Signpost Icon for "آدرس‌ها" matching uploaded reference image row 4
  const SignpostIcon = () => (
    <svg
      className="w-5 h-5 text-neutral-800 shrink-0"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.7"
      strokeLinecap="round"
      strokeLinejoin="round"
    >
      <line x1="12" y1="2" x2="12" y2="22" />
      <rect x="4" y="5" width="16" height="4" rx="1.5" />
      <rect x="4" y="13" width="16" height="4" rx="1.5" />
    </svg>
  );

  // SUB-VIEW 1: ORDERS (سفارش‌ها)
  if (currentSubView === 'orders') {
    return (
      <div className="bg-white text-neutral-900 min-h-screen font-tommy selection:bg-[#171717] selection:text-white" dir="rtl">
        <main className="max-w-[620px] mx-auto px-4 sm:px-6 pt-6 sm:pt-8 pb-24">
          <div className="flex items-center justify-between pb-4 border-b border-neutral-200/80 mb-6">
            <h2 className="text-[12.5px] font-bold text-neutral-900" style={{ fontFamily: "'YekanBakh', 'Yekan Bakh', sans-serif" }}>
              سفارش‌ها {orders.length > 0 && `(${toPersianDigits(orders.length)})`}
            </h2>
            <button
              type="button"
              onClick={() => setCurrentSubView('menu')}
              className="inline-flex items-center gap-1 text-[11px] font-medium text-neutral-600 hover:text-black transition-colors cursor-pointer group"
              style={{ fontFamily: "'YekanBakh', 'Yekan Bakh', sans-serif" }}
            >
              <span>بازگشت</span>
              <ChevronLeft className="w-4 h-4 transition-transform group-hover:-translate-x-0.5" strokeWidth={1.8} />
            </button>
          </div>

          {orders.length === 0 ? (
            <div className="py-16 text-center border border-neutral-200 bg-neutral-50/50 space-y-3">
              <Package className="w-8 h-8 mx-auto text-neutral-400 stroke-[1.5]" />
              <h3 className="text-[12.5px] font-semibold text-neutral-900" style={{ fontFamily: "'YekanBakh', 'Yekan Bakh', sans-serif" }}>
                سفارش فعالی در حال پردازش نیست
              </h3>
              <p className="text-[11px] text-neutral-500 max-w-sm mx-auto" style={{ fontFamily: "'YekanBakh', 'Yekan Bakh', sans-serif" }}>
                تمامی سفارش‌های ثبت‌شده پس از تحویل به مامور ارسال، کد رهگیری پیامکی دریافت خواهند کرد.
              </p>
              <div className="pt-2">
                <button
                  type="button"
                  onClick={() => onNavigateToProducts({ gender: 'all' })}
                  className="px-5 py-2.5 bg-black text-white text-[11px] font-medium cursor-pointer rounded-none hover:bg-neutral-800 transition-colors"
                  style={{ fontFamily: "'YekanBakh', 'Yekan Bakh', sans-serif" }}
                >
                  مرور محصولات
                </button>
              </div>
            </div>
          ) : (
            <div className="space-y-4" style={{ fontFamily: "'YekanBakh', 'Yekan Bakh', sans-serif" }}>
              {orders.map((order) => {
                const totalItemsCount = order.items.reduce((sum, item) => sum + item.quantity, 0);
                return (
                  <div
                    key={order.id}
                    className="border border-neutral-200 bg-white rounded-xl p-3.5 sm:p-4 hover:border-neutral-400 transition-all shadow-2xs space-y-3"
                  >
                    {/* Top Row: Status badge & date on right, Tracking code on left */}
                    <div className="flex items-center justify-between pb-2.5 border-b border-neutral-100">
                      <div className="flex items-center gap-2">
                        <span className="inline-flex items-center gap-1.5 text-[10px] font-semibold bg-emerald-50 text-emerald-800 border border-emerald-200 px-2 py-0.5 rounded-full">
                          <span className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse" />
                          <span>{order.status}</span>
                        </span>
                        <span className="text-[10.5px] text-neutral-400 font-normal">
                          {toPersianDigits(order.date)}
                        </span>
                      </div>

                      <div className="text-[11px] text-neutral-700 font-medium">
                        <span>کد رهگیری: </span>
                        <span className="font-bold text-neutral-900 font-mono">#{order.trackingCode}</span>
                      </div>
                    </div>

                    {/* Middle: Method and Gateway info */}
                    <div className="flex flex-wrap items-center gap-2 text-[10.5px] text-neutral-500">
                      <span>شیوه ارسال: <strong className="text-neutral-800 font-medium">{order.deliveryMethod === 'courier' ? 'ارسال با پیک' : 'ارسال با پست'}</strong></span>
                      <span>•</span>
                      <span>درگاه: <strong className="text-neutral-800 font-medium">{order.paymentGateway === 'zarinpal' ? 'زرین‌پال' : 'زیبال'}</strong></span>
                      <span>•</span>
                      <span>گیرنده: <strong className="text-neutral-800 font-medium">{order.recipient.name}</strong></span>
                    </div>

                    {/* Products Gallery */}
                    <div className="flex items-center gap-2 overflow-x-auto py-1 scrollbar-none">
                      {order.items.map((item, idx) => (
                        <div
                          key={idx}
                          onClick={() => onOpenProductDetail(item.product)}
                          className="flex items-center gap-2 border border-neutral-150 bg-neutral-50/60 p-1.5 rounded-lg shrink-0 cursor-pointer hover:border-neutral-400 transition-colors group"
                        >
                          <img
                            src={item.product.image}
                            alt={item.product.name}
                            className="w-10 h-12 object-cover rounded border border-neutral-200 group-hover:scale-102 transition-transform"
                          />
                          <div className="text-[10px] text-right">
                            <p className="font-semibold text-neutral-900 line-clamp-1 max-w-[120px]">{item.product.name}</p>
                            <p className="text-neutral-500 mt-0.5">
                              سایز {toPersianDigits(item.selectedSize)} • {toPersianDigits(item.quantity)} عدد
                            </p>
                          </div>
                        </div>
                      ))}
                    </div>

                    {/* Bottom Row: Item count on right, Paid amount on left */}
                    <div className="flex items-center justify-between pt-2.5 border-t border-neutral-100 text-[11px]">
                      <span className="text-neutral-500">
                        تعداد اقلام: <strong className="text-neutral-900 font-semibold">{toPersianDigits(totalItemsCount)} کالا</strong>
                      </span>

                      <div className="flex items-center gap-2">
                        {order.discountAmount > 0 && (
                          <span className="text-[10px] text-emerald-700 bg-emerald-50 px-1.5 py-0.2 rounded font-medium">
                            {formatTomanPrice(order.discountAmount)} تخفیف
                          </span>
                        )}
                        <span className="text-neutral-600">
                          مبلغ پرداخت شده: <strong className="text-xs sm:text-[13px] text-neutral-900 font-bold">{formatTomanPrice(order.finalTotal)}</strong>
                        </span>
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </main>
      </div>
    );
  }

  // SUB-VIEW 2: WISHLIST (علاقمندی‌ها)
  if (currentSubView === 'wishlist') {
    return (
      <div className="bg-white text-neutral-900 min-h-screen font-tommy selection:bg-[#171717] selection:text-white" dir="rtl">
        <main className="max-w-[620px] mx-auto px-4 sm:px-6 pt-6 sm:pt-8 pb-24">
          <div className="flex items-center justify-between pb-4 border-b border-neutral-200/80 mb-6">
            <h2 className="text-[12.5px] font-bold text-neutral-900" style={{ fontFamily: "'YekanBakh', 'Yekan Bakh', sans-serif" }}>
              علاقمندی‌ها ({toPersianDigits(savedWishlistProducts.length)})
            </h2>
            <button
              type="button"
              onClick={() => setCurrentSubView('menu')}
              className="inline-flex items-center gap-1 text-[11px] font-medium text-neutral-600 hover:text-black transition-colors cursor-pointer group"
              style={{ fontFamily: "'YekanBakh', 'Yekan Bakh', sans-serif" }}
            >
              <span>بازگشت</span>
              <ChevronLeft className="w-4 h-4 transition-transform group-hover:-translate-x-0.5" strokeWidth={1.8} />
            </button>
          </div>

          {savedWishlistProducts.length === 0 ? (
            <div className="py-16 text-center space-y-3 border border-neutral-200 bg-neutral-50/50">
              <Heart className="w-8 h-8 mx-auto text-neutral-400 stroke-[1.5]" />
              <h3 className="text-[12.5px] font-semibold text-neutral-900" style={{ fontFamily: "'YekanBakh', 'Yekan Bakh', sans-serif" }}>
                لیست علاقمندی‌های شما خالی است
              </h3>
              <p className="text-[11px] text-neutral-500 max-w-xs mx-auto" style={{ fontFamily: "'YekanBakh', 'Yekan Bakh', sans-serif" }}>
                با کلیک روی آیکون قلب در کنار محصولات، آیتم‌های موردعلاقه خود را اینجا ذخیره کنید.
              </p>
              <button
                type="button"
                onClick={() => onNavigateToProducts({ gender: 'all' })}
                className="mt-3 px-5 py-2.5 bg-black text-white text-[11px] font-medium cursor-pointer rounded-none hover:bg-neutral-800 transition-colors"
                style={{ fontFamily: "'YekanBakh', 'Yekan Bakh', sans-serif" }}
              >
                مشاهده کالکشن محصولات
              </button>
            </div>
          ) : (
            <div className="grid grid-cols-2 sm:grid-cols-3 gap-3">
              {savedWishlistProducts.map((p) => (
                <div
                  key={p.id}
                  className="border border-neutral-200/80 p-3 hover:border-black transition-all group bg-white relative flex flex-col justify-between"
                >
                  <div
                    onClick={() => onOpenProductDetail(p)}
                    className="cursor-pointer"
                  >
                    <div className="aspect-[3/4] bg-neutral-100 overflow-hidden mb-2 relative">
                      <img
                        src={p.image}
                        alt={p.name}
                        className="w-full h-full object-cover object-center group-hover:scale-105 transition-transform duration-500"
                      />
                      {onToggleGarderob && (
                        <button
                          type="button"
                          onClick={(e) => {
                            e.stopPropagation();
                            onToggleGarderob(p);
                          }}
                          className="absolute top-2 left-2 w-7 h-7 bg-white/90 backdrop-blur-xs flex items-center justify-center text-neutral-600 hover:text-red-600 hover:bg-white transition-colors cursor-pointer shadow-xs"
                          title="حذف از علاقمندی‌ها"
                          aria-label="حذف از علاقمندی‌ها"
                        >
                          <Trash2 className="w-3.5 h-3.5" />
                        </button>
                      )}
                    </div>
                    <h4 className="text-[11px] font-medium text-neutral-900 line-clamp-1" style={{ fontFamily: "'YekanBakh', 'Yekan Bakh', sans-serif" }}>
                      {p.name}
                    </h4>
                    <p className="text-[10.5px] text-neutral-600 font-medium mt-0.5" style={{ fontFamily: "'YekanBakh', 'Yekan Bakh', sans-serif" }}>
                      {formatTomanPrice(p.price)}
                    </p>
                  </div>
                </div>
              ))}
            </div>
          )}
        </main>
      </div>
    );
  }

  // SUB-VIEW 3: ADDRESSES (آدرس‌ها)
  if (currentSubView === 'addresses') {
    return (
      <div className="bg-white text-neutral-900 min-h-screen font-tommy selection:bg-[#171717] selection:text-white" dir="rtl">
        <main className="max-w-[620px] mx-auto px-4 sm:px-6 pt-6 sm:pt-8 pb-24" style={{ fontFamily: "'YekanBakh', 'Yekan Bakh', sans-serif" }}>
          <div className="flex items-center justify-between pb-4 border-b border-neutral-200/80 mb-6">
            <h2 className="text-[12.5px] font-bold text-neutral-900">
              آدرس‌ها
            </h2>
            <button
              type="button"
              onClick={() => {
                setIsAddressFormOpen(false);
                setCurrentSubView('menu');
              }}
              className="inline-flex items-center gap-1 text-[11px] font-medium text-neutral-600 hover:text-black transition-colors cursor-pointer group"
            >
              <span>بازگشت</span>
              <ChevronLeft className="w-4 h-4 transition-transform group-hover:-translate-x-0.5" strokeWidth={1.8} />
            </button>
          </div>

          {noticeMsg && (
            <div className="mb-5 p-2.5 bg-[#eaf7ee] border border-[#bfe7ca] text-[#1b5e20] text-[11px] flex items-center gap-2">
              <Check className="w-3.5 h-3.5 text-[#2e7d32]" />
              <span>{noticeMsg}</span>
            </div>
          )}

          {!isAddressFormOpen ? (
            <div className="space-y-4">
              <div className="flex items-center justify-between">
                <span className="text-[11.5px] font-medium text-neutral-800">
                  آدرس‌های ثبت‌شده ({toPersianDigits(addresses.length)})
                </span>
                <button
                  type="button"
                  onClick={handleOpenAddAddress}
                  className="inline-flex items-center gap-1.5 px-3 py-1.5 text-[10.5px] font-medium bg-[#171717] hover:bg-neutral-800 text-white transition-colors cursor-pointer rounded-none"
                >
                  <Plus className="w-3.5 h-3.5" />
                  <span>افزودن آدرس جدید</span>
                </button>
              </div>

              {addresses.length === 0 ? (
                <div className="py-12 px-4 text-center border border-dashed border-neutral-300 bg-neutral-50/60">
                  <SignpostIcon />
                  <p className="text-[12px] font-medium text-neutral-800 mt-2 mb-1">
                    هنوز آدرسی ثبت نکرده‌اید
                  </p>
                  <p className="text-[10.5px] text-neutral-500 mb-4">
                    برای ارسال سفارش‌ها، آدرس تحویل خود را اضافه کنید.
                  </p>
                  <button
                    type="button"
                    onClick={handleOpenAddAddress}
                    className="px-4 py-2 bg-black text-white text-[11px] font-medium cursor-pointer rounded-none hover:bg-neutral-800 transition-colors"
                  >
                    + افزودن اولین آدرس
                  </button>
                </div>
              ) : (
                <div className="space-y-3">
                  {addresses.map((addr) => (
                    <div
                      key={addr.id}
                      className={`p-3.5 border transition-all rounded-none bg-white relative ${
                        addr.isDefault
                          ? 'border-neutral-900 shadow-[0_1px_4px_rgba(0,0,0,0.04)]'
                          : 'border-neutral-200 hover:border-neutral-400'
                      }`}
                    >
                      <div className="flex items-center justify-between mb-2">
                        <div className="flex items-center gap-2">
                          <span className="text-[12px] font-bold text-neutral-900">
                            {addr.title}
                          </span>
                          {addr.isDefault && (
                            <span className="text-[9.5px] bg-neutral-900 text-white px-1.5 py-0.5 rounded-none font-normal">
                              آدرس پیش‌فرض
                            </span>
                          )}
                        </div>
                        <div className="flex items-center gap-2">
                          <button
                            type="button"
                            onClick={() => handleOpenEditAddress(addr)}
                            className="text-neutral-500 hover:text-neutral-900 transition-colors p-1"
                            title="ویرایش آدرس"
                          >
                            <Edit3 className="w-3.5 h-3.5" />
                          </button>
                          <button
                            type="button"
                            onClick={() => handleDeleteAddress(addr.id)}
                            className="text-neutral-500 hover:text-red-600 transition-colors p-1"
                            title="حذف آدرس"
                          >
                            <Trash2 className="w-3.5 h-3.5" />
                          </button>
                        </div>
                      </div>

                      <p className="text-[11px] text-neutral-700 leading-relaxed mb-2">
                        {addr.province}، {addr.city}، {addr.fullAddress}
                        {addr.plaque && `، پلاک ${toPersianDigits(addr.plaque)}`}
                        {addr.unit && `، واحد ${toPersianDigits(addr.unit)}`}
                      </p>

                      <div className="flex flex-wrap items-center gap-y-1 gap-x-4 text-[10px] text-neutral-500 border-t border-neutral-100 pt-2">
                        {addr.postalCode && <span>کد پستی: {toPersianDigits(addr.postalCode)}</span>}
                        {addr.recipientName && <span>تحویل‌گیرنده: {addr.recipientName}</span>}
                        {addr.recipientPhone && <span>شماره تماس: {toPersianDigits(addr.recipientPhone)}</span>}
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          ) : (
            <form onSubmit={handleSaveAddress} className="space-y-3.5 bg-neutral-50/50 p-4 sm:p-5 border border-neutral-200">
              <div className="flex items-center justify-between pb-2 border-b border-neutral-200 mb-2">
                <h3 className="text-[12px] font-bold text-neutral-900">
                  {editingAddressId ? 'ویرایش آدرس' : 'افزودن آدرس جدید'}
                </h3>
                <button
                  type="button"
                  onClick={() => setIsAddressFormOpen(false)}
                  className="text-[10.5px] text-neutral-500 hover:text-black cursor-pointer"
                >
                  بستن
                </button>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
                <div>
                  <label className="block text-[10px] text-neutral-600 mb-1">عنوان (منزل، شرکت و ...)</label>
                  <input
                    type="text"
                    required
                    value={addressForm.title}
                    onChange={(e) => setAddressForm({ ...addressForm, title: e.target.value })}
                    className="w-full h-9 px-2.5 border border-neutral-300 focus:border-black rounded-none text-[11.5px] bg-white"
                  />
                </div>
                <div>
                  <label className="block text-[10px] text-neutral-600 mb-1">استان</label>
                  <input
                    type="text"
                    required
                    value={addressForm.province}
                    onChange={(e) => setAddressForm({ ...addressForm, province: e.target.value })}
                    className="w-full h-9 px-2.5 border border-neutral-300 focus:border-black rounded-none text-[11.5px] bg-white"
                  />
                </div>
                <div>
                  <label className="block text-[10px] text-neutral-600 mb-1">شهر</label>
                  <input
                    type="text"
                    required
                    value={addressForm.city}
                    onChange={(e) => setAddressForm({ ...addressForm, city: e.target.value })}
                    className="w-full h-9 px-2.5 border border-neutral-300 focus:border-black rounded-none text-[11.5px] bg-white"
                  />
                </div>
              </div>

              <div>
                <label className="block text-[10px] text-neutral-600 mb-1">نشانی دقیق پستی</label>
                <textarea
                  required
                  rows={2}
                  value={addressForm.fullAddress}
                  onChange={(e) => setAddressForm({ ...addressForm, fullAddress: e.target.value })}
                  placeholder="خیابان، کوچه، پلاک، واحد..."
                  className="w-full p-2.5 border border-neutral-300 focus:border-black rounded-none text-[11.5px] bg-white outline-hidden"
                />
              </div>

              <div className="grid grid-cols-3 gap-2.5">
                <div>
                  <label className="block text-[10px] text-neutral-600 mb-1">پلاک</label>
                  <input
                    type="text"
                    value={addressForm.plaque}
                    onChange={(e) => setAddressForm({ ...addressForm, plaque: e.target.value })}
                    className="w-full h-9 px-2.5 border border-neutral-300 focus:border-black rounded-none text-[11.5px] bg-white"
                  />
                </div>
                <div>
                  <label className="block text-[10px] text-neutral-600 mb-1">واحد</label>
                  <input
                    type="text"
                    value={addressForm.unit}
                    onChange={(e) => setAddressForm({ ...addressForm, unit: e.target.value })}
                    className="w-full h-9 px-2.5 border border-neutral-300 focus:border-black rounded-none text-[11.5px] bg-white"
                  />
                </div>
                <div>
                  <label className="block text-[10px] text-neutral-600 mb-1">کد پستی (۱۰ رقم)</label>
                  <input
                    type="text"
                    maxLength={10}
                    value={addressForm.postalCode}
                    onChange={(e) => setAddressForm({ ...addressForm, postalCode: e.target.value })}
                    className="w-full h-9 px-2.5 border border-neutral-300 focus:border-black rounded-none text-[11.5px] bg-white"
                  />
                </div>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 pt-1">
                <div>
                  <label className="block text-[10px] text-neutral-600 mb-1">نام و نام خانوادگی تحویل‌گیرنده</label>
                  <input
                    type="text"
                    value={addressForm.recipientName}
                    onChange={(e) => setAddressForm({ ...addressForm, recipientName: e.target.value })}
                    className="w-full h-9 px-2.5 border border-neutral-300 focus:border-black rounded-none text-[11.5px] bg-white"
                  />
                </div>
                <div>
                  <label className="block text-[10px] text-neutral-600 mb-1">شماره تماس تحویل‌گیرنده</label>
                  <input
                    type="tel"
                    value={addressForm.recipientPhone}
                    onChange={(e) => setAddressForm({ ...addressForm, recipientPhone: e.target.value })}
                    className="w-full h-9 px-2.5 border border-neutral-300 focus:border-black rounded-none text-[11.5px] bg-white"
                  />
                </div>
              </div>

              <div className="flex items-center gap-2 pt-1">
                <input
                  type="checkbox"
                  id="isDefaultAddr"
                  checked={addressForm.isDefault}
                  onChange={(e) => setAddressForm({ ...addressForm, isDefault: e.target.checked })}
                  className="w-4 h-4 accent-black rounded-none cursor-pointer"
                />
                <label htmlFor="isDefaultAddr" className="text-[11px] text-neutral-700 cursor-pointer select-none">
                  انتخاب به عنوان آدرس پیش‌فرض تحویل
                </label>
              </div>

              <div className="pt-2 flex items-center gap-2">
                <button
                  type="submit"
                  className="flex-1 h-9.5 bg-[#171717] hover:bg-neutral-800 text-white text-[11px] font-medium rounded-none transition-colors cursor-pointer"
                >
                  ذخیره آدرس
                </button>
                <button
                  type="button"
                  onClick={() => setIsAddressFormOpen(false)}
                  className="h-9.5 px-4 border border-neutral-200 hover:border-black text-neutral-600 rounded-none text-[11px] transition-colors cursor-pointer"
                >
                  انصراف
                </button>
              </div>
            </form>
          )}
        </main>
      </div>
    );
  }

  // SUB-VIEW 4: PERSONAL INFO (اطلاعات حساب کاربری)
  if (currentSubView === 'personal-info') {
    return (
      <div className="bg-white text-neutral-900 min-h-screen font-tommy selection:bg-[#171717] selection:text-white" dir="rtl">
        <main className="max-w-[620px] mx-auto px-4 sm:px-6 pt-6 sm:pt-8 pb-24" style={{ fontFamily: "'YekanBakh', 'Yekan Bakh', sans-serif" }}>
          <div className="flex items-center justify-between pb-4 border-b border-neutral-200/80 mb-6">
            <h2 className="text-[12.5px] font-bold text-neutral-900">
              اطلاعات حساب کاربری
            </h2>
            <button
              type="button"
              onClick={() => setCurrentSubView('menu')}
              className="inline-flex items-center gap-1 text-[11px] font-medium text-neutral-600 hover:text-black transition-colors cursor-pointer group"
            >
              <span>بازگشت</span>
              <ChevronLeft className="w-4 h-4 transition-transform group-hover:-translate-x-0.5" strokeWidth={1.8} />
            </button>
          </div>

          <form onSubmit={handleSavePersonalInfo} className="space-y-4">
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
              <div>
                <label className="block text-[10.5px] text-neutral-600 mb-1 font-medium">نام</label>
                <input
                  type="text"
                  value={firstName}
                  onChange={(e) => setFirstName(e.target.value)}
                  placeholder="مثال: نگین"
                  className="w-full h-9.5 px-3 border border-neutral-300 focus:border-black rounded-none text-[12px] text-neutral-900 outline-hidden bg-white"
                />
              </div>

              <div>
                <label className="block text-[10.5px] text-neutral-600 mb-1 font-medium">نام خانوادگی</label>
                <input
                  type="text"
                  value={lastName}
                  onChange={(e) => setLastName(e.target.value)}
                  placeholder="مثال: اسدی"
                  className="w-full h-9.5 px-3 border border-neutral-300 focus:border-black rounded-none text-[12px] text-neutral-900 outline-hidden bg-white"
                />
              </div>
            </div>

            <div>
              <label className="block text-[10.5px] text-neutral-600 mb-1 font-medium">
                شماره موبایل (شماره ثبت‌نامی)
              </label>
              <div className="relative">
                <input
                  type="text"
                  readOnly
                  disabled
                  value={toPersianDigits(userPhone)}
                  className="w-full h-9.5 px-3 border border-neutral-200 bg-neutral-100/70 text-neutral-600 rounded-none text-[12px] outline-hidden cursor-not-allowed select-none"
                />
                <span className="absolute left-3 top-1/2 -translate-y-1/2 text-[9.5px] text-emerald-700 bg-emerald-50 border border-emerald-200 px-1.5 py-0.5 rounded-none">
                  تایید شده
                </span>
              </div>
            </div>

            <div>
              <label className="block text-[10.5px] text-neutral-600 mb-1 font-medium">
                کد ملی <span className="text-neutral-400 font-normal">(اختیاری - جهت صدور فاکتور)</span>
              </label>
              <input
                type="text"
                maxLength={10}
                value={nationalCode}
                onChange={(e) => setNationalCode(e.target.value)}
                placeholder="۱۰ رقم بدون خط تیره"
                className="w-full h-9.5 px-3 border border-neutral-300 focus:border-black rounded-none text-[12px] text-neutral-900 outline-hidden bg-white"
              />
            </div>

            <div>
              <label className="block text-[10.5px] text-neutral-600 mb-1 font-medium">
                ایمیل <span className="text-neutral-400 font-normal">(اختیاری)</span>
              </label>
              <input
                type="email"
                dir="ltr"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                placeholder="name@example.com"
                className="w-full h-9.5 px-3 border border-neutral-300 focus:border-black rounded-none text-[12px] text-neutral-900 outline-hidden bg-white text-right"
              />
            </div>

            <div className="pt-3 flex items-center gap-2">
              <button
                type="submit"
                className="flex-1 h-10 bg-[#171717] hover:bg-neutral-800 text-white text-[11.5px] font-medium rounded-none transition-colors cursor-pointer"
              >
                ذخیره تغییرات
              </button>
              <button
                type="button"
                onClick={() => setCurrentSubView('menu')}
                className="h-10 px-5 border border-neutral-200 hover:border-black text-neutral-700 rounded-none text-[11.5px] transition-colors cursor-pointer"
              >
                انصراف
              </button>
            </div>
          </form>
        </main>
      </div>
    );
  }

  // MAIN VIEW: Menu List exactly matching user's uploaded reference image (image_9bbf1cd0.png)
  return (
    <div className="bg-white text-neutral-900 min-h-screen font-tommy selection:bg-[#171717] selection:text-white" dir="rtl">
      
      {/* Main Container */}
      <main className="max-w-[620px] mx-auto px-4 sm:px-6 pt-6 sm:pt-8 pb-24">
        
        {/* COMPACT TOP PROFILE HEADER (Phone number, user name, and small grey edit pen icon) */}
        <section className="bg-white border border-neutral-200/90 rounded-none px-4 py-3 mb-6 flex items-center justify-between">
          <div className="text-right">
            {userName ? (
              <>
                <h1
                  className="text-[12.5px] sm:text-[13px] font-semibold text-neutral-900 leading-tight mb-0.5"
                  style={{ fontFamily: "'YekanBakh', 'Yekan Bakh', sans-serif" }}
                >
                  {userName}
                </h1>
                <p
                  className="text-[10px] sm:text-[10.5px] text-neutral-500 font-normal tracking-wide"
                  style={{ fontFamily: "'YekanBakh', 'Yekan Bakh', sans-serif" }}
                >
                  {toPersianDigits(userPhone)}
                </p>
              </>
            ) : (
              <p
                className="text-[11.5px] sm:text-[12px] font-medium text-neutral-800 tracking-wide"
                style={{ fontFamily: "'YekanBakh', 'Yekan Bakh', sans-serif" }}
              >
                {toPersianDigits(userPhone)}
              </p>
            )}
          </div>

          <div>
            <button
              type="button"
              onClick={() => setCurrentSubView('personal-info')}
              className="p-1.5 text-neutral-400 hover:text-neutral-800 hover:bg-neutral-100 transition-colors rounded-none cursor-pointer flex items-center justify-center group"
              title="ویرایش اطلاعات حساب"
              aria-label="ویرایش اطلاعات حساب"
            >
              <svg
                className="w-3.5 h-3.5 transition-transform duration-200 group-hover:scale-110"
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                strokeWidth="1.8"
                strokeLinecap="round"
                strokeLinejoin="round"
              >
                <path d="M17.5 3.5a2.1 2.1 0 0 1 3 3L8.5 18.5l-4.5 1 1-4.5L17.5 3.5z" />
                <path d="M11 21h7" />
              </svg>
            </button>
          </div>
        </section>

        {noticeMsg && (
          <div
            className="mb-4 p-2.5 bg-[#eaf7ee] border border-[#bfe7ca] text-[#1b5e20] text-[11px] flex items-center gap-2"
            style={{ fontFamily: "'YekanBakh', 'Yekan Bakh', sans-serif" }}
          >
            <Check className="w-3.5 h-3.5 text-[#2e7d32]" />
            <span>{noticeMsg}</span>
          </div>
        )}

        {/* PROFILE MENU LIST (Pixel-perfect matching uploaded reference image image_9bbf1cd0.png) */}
        <div className="bg-white border-t border-b border-neutral-100 divide-y divide-neutral-100" style={{ fontFamily: "'YekanBakh', 'Yekan Bakh', sans-serif" }}>
          
          {/* 1. سفارش‌ها */}
          <button
            type="button"
            onClick={() => setCurrentSubView('orders')}
            className="w-full flex items-center justify-between py-3.5 sm:py-4 px-1 hover:bg-neutral-50/60 transition-colors group cursor-pointer text-right"
          >
            <div className="flex items-center gap-3">
              <ShoppingBag className="w-4.5 h-4.5 text-neutral-800 shrink-0 group-hover:scale-105 transition-transform" strokeWidth={1.7} />
              <span className="text-[11.5px] sm:text-[12px] font-medium text-[#222222] group-hover:text-black transition-colors">
                سفارش‌ها
              </span>
            </div>
            <div className="flex items-center gap-1.5">
              {orders.length > 0 && (
                <span className="text-[10px] bg-neutral-100 text-neutral-700 px-1.5 py-0.2 rounded font-medium">
                  {toPersianDigits(orders.length)}
                </span>
              )}
              <ChevronLeft className="w-3.5 h-3.5 text-neutral-400 group-hover:text-neutral-700 group-hover:-translate-x-0.5 transition-all" strokeWidth={1.6} />
            </div>
          </button>

          {/* 2. علاقمندی‌ها */}
          <button
            type="button"
            onClick={() => setCurrentSubView('wishlist')}
            className="w-full flex items-center justify-between py-3.5 sm:py-4 px-1 hover:bg-neutral-50/60 transition-colors group cursor-pointer text-right"
          >
            <div className="flex items-center gap-3">
              <Heart className="w-4.5 h-4.5 text-neutral-800 shrink-0 group-hover:scale-105 transition-transform" strokeWidth={1.7} />
              <span className="text-[11.5px] sm:text-[12px] font-medium text-[#222222] group-hover:text-black transition-colors">
                علاقمندی‌ها
              </span>
            </div>
            <ChevronLeft className="w-3.5 h-3.5 text-neutral-400 group-hover:text-neutral-700 group-hover:-translate-x-0.5 transition-all" strokeWidth={1.6} />
          </button>

          {/* 3. آدرس‌ها (بدون نمایش تعداد در منو) */}
          <button
            type="button"
            onClick={() => setCurrentSubView('addresses')}
            className="w-full flex items-center justify-between py-3.5 sm:py-4 px-1 hover:bg-neutral-50/60 transition-colors group cursor-pointer text-right"
          >
            <div className="flex items-center gap-3">
              <SignpostIcon />
              <span className="text-[11.5px] sm:text-[12px] font-medium text-[#222222] group-hover:text-black transition-colors">
                آدرس‌ها
              </span>
            </div>
            <ChevronLeft className="w-3.5 h-3.5 text-neutral-400 group-hover:text-neutral-700 group-hover:-translate-x-0.5 transition-all" strokeWidth={1.6} />
          </button>

          {/* 4. اطلاعات حساب کاربری */}
          <button
            type="button"
            onClick={() => setCurrentSubView('personal-info')}
            className="w-full flex items-center justify-between py-3.5 sm:py-4 px-1 hover:bg-neutral-50/60 transition-colors group cursor-pointer text-right"
          >
            <div className="flex items-center gap-3">
              <UserIcon className="w-4.5 h-4.5 text-neutral-800 shrink-0 group-hover:scale-105 transition-transform" strokeWidth={1.7} />
              <span className="text-[11.5px] sm:text-[12px] font-medium text-[#222222] group-hover:text-black transition-colors">
                اطلاعات حساب کاربری
              </span>
            </div>
            <ChevronLeft className="w-3.5 h-3.5 text-neutral-400 group-hover:text-neutral-700 group-hover:-translate-x-0.5 transition-all" strokeWidth={1.6} />
          </button>

          {/* 5. خروج از حساب */}
          <button
            type="button"
            onClick={() => setIsLogoutModalOpen(true)}
            className="w-full flex items-center justify-between py-3.5 sm:py-4 px-1 hover:bg-neutral-50/60 transition-colors group cursor-pointer text-right"
          >
            <div className="flex items-center gap-3">
              <LogOut className="w-4.5 h-4.5 text-neutral-800 shrink-0 group-hover:scale-105 transition-transform" strokeWidth={1.7} />
              <span className="text-[11.5px] sm:text-[12px] font-medium text-[#222222] group-hover:text-black transition-colors">
                خروج از حساب
              </span>
            </div>
            <ChevronLeft className="w-3.5 h-3.5 text-neutral-400 group-hover:text-neutral-700 group-hover:-translate-x-0.5 transition-all" strokeWidth={1.6} />
          </button>

        </div>

        {/* Back to Home CTA */}
        <div className="text-center mt-16 sm:mt-20">
          <button
            type="button"
            onClick={onNavigateHome}
            className="text-[11px] text-neutral-500 hover:text-black transition-colors cursor-pointer inline-flex items-center gap-1 group"
            style={{ fontFamily: "'YekanBakh', 'Yekan Bakh', sans-serif" }}
          >
            <span>بازگشت به صفحه اصلی</span>
            <ChevronLeft className="w-3.5 h-3.5 transition-transform group-hover:-translate-x-0.5" strokeWidth={1.8} />
          </button>
        </div>

      </main>

      {/* Logout Confirmation Modal */}
      {isLogoutModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-xs animate-in fade-in duration-200">
          <div
            className="bg-white border border-neutral-200 p-6 max-w-sm w-full rounded-none shadow-2xl text-right animate-in zoom-in-95 duration-200"
            style={{ fontFamily: "'YekanBakh', 'Yekan Bakh', sans-serif" }}
          >
            <h3 className="text-[13.5px] font-bold text-neutral-900 mb-2">
              خروج از حساب کاربری
            </h3>
            <p className="text-[11.5px] text-neutral-600 mb-6 leading-relaxed">
              آیا از خروج از حساب کاربری لنگه اطمینان دارید؟
            </p>
            <div className="flex items-center gap-2">
              <button
                type="button"
                onClick={() => {
                  setIsLogoutModalOpen(false);
                  onLogout();
                }}
                className="flex-1 h-9.5 bg-[#171717] hover:bg-neutral-800 text-white text-[11px] font-medium rounded-none transition-colors cursor-pointer"
              >
                بله، خروج
              </button>
              <button
                type="button"
                onClick={() => setIsLogoutModalOpen(false)}
                className="flex-1 h-9.5 border border-neutral-200 hover:border-black text-neutral-700 rounded-none text-[11px] transition-colors cursor-pointer"
              >
                انصراف
              </button>
            </div>
          </div>
        </div>
      )}

    </div>
  );
};
